def transform(grid):
    h, w = len(grid), len(grid[0])

    # The colored lattice points are the non-background values at crossings
    # of uniform separator rows and columns. Find those crossing coordinates.
    rows = [r for r in range(h) if len(set(grid[r])) <= 2]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) <= 2]

    # Keep only rows/columns that actually contain non-background crossing
    # markers, then read the markers in lattice order.
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(v == x for row in grid for v in row))
    points = [[grid[r][c] for c in cols] for r in rows]

    def squeeze(matrix):
        # Collapse consecutive duplicate lattice samples (thick separators).
        changed = True
        while changed:
            changed = False
            if len(matrix) > 1:
                keep = [0]
                for i in range(1, len(matrix)):
                    if matrix[i] != matrix[keep[-1]]:
                        keep.append(i)
                    else:
                        changed = True
                matrix = [matrix[i] for i in keep]
            if matrix and len(matrix[0]) > 1:
                keep = [0]
                for j in range(1, len(matrix[0])):
                    if any(row[j] != row[keep[-1]] for row in matrix):
                        keep.append(j)
                    else:
                        changed = True
                matrix = [[row[j] for j in keep] for row in matrix]
        return matrix

    points = squeeze(points)
    return points
